import{_ as m,C as o,o as g,c as b,j as t,a,E as s,a8 as v}from"./chunks/framework.27XeWUA0.js";const n="/schedule-dashboard/thumbs/yt/_0SQh8a1Osk-640.webp",f="/schedule-dashboard/thumbs/yt/_0SQh8a1Osk-1280.webp",r="/schedule-dashboard/thumbs/yt/ZJjRgvjhq3M-640.webp",k="/schedule-dashboard/thumbs/yt/ZJjRgvjhq3M-1280.webp",i="/schedule-dashboard/thumbs/yt/gdzsJZJ6DDs-640.webp",y="/schedule-dashboard/thumbs/yt/gdzsJZJ6DDs-1280.webp",l="/schedule-dashboard/thumbs/yt/maitMe9HCvw-640.webp",_="/schedule-dashboard/thumbs/yt/maitMe9HCvw-1280.webp",h="/schedule-dashboard/thumbs/yt/RdQCY_-SXbA-640.webp",A="/schedule-dashboard/thumbs/yt/RdQCY_-SXbA-1280.webp",c="/schedule-dashboard/thumbs/yt/kIlVNGZZr8o-640.webp",C="/schedule-dashboard/thumbs/yt/kIlVNGZZr8o-1280.webp",p="/schedule-dashboard/thumbs/yt/0acRokoODvo-640.webp",S="/schedule-dashboard/thumbs/yt/0acRokoODvo-1280.webp",w="/schedule-dashboard/thumbs/yt/ZtOA71C_Nco-640.webp",I="/schedule-dashboard/thumbs/yt/ZtOA71C_Nco-1280.webp",H=JSON.parse('{"title":"AI Digest · Sun 08 Nov 2026","description":"","frontmatter":{"aside":false,"outline":false},"headers":[],"params":{"date":"2026-11-08","routine":"digest"},"relativePath":"digest/2026-11-08.md","filePath":"digest/[date].md"}'),Z={name:"digest/2026-11-08.md"},O=n+" 640w, "+f+" 1280w",R=r+" 640w, "+k+" 1280w",M=i+" 640w, "+y+" 1280w",x=l+" 640w, "+_+" 1280w",D=h+" 640w, "+A+" 1280w",N=c+" 640w, "+C+" 1280w",J=p+" 640w, "+S+" 1280w",j=w+" 640w, "+I+" 1280w",G={id:"ai-digest-·-sun-08-nov-2026",tabindex:"-1"};function P(q,e,T,z,V,Q){const d=o("Badge"),u=o("DayFilter");return g(),b("div",null,[t("h1",G,[e[0]||(e[0]=a("AI Digest · Sun 08 Nov 2026 ",-1)),s(d,{type:"tip",text:"8"}),e[1]||(e[1]=a()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#ai-digest-·-sun-08-nov-2026","aria-label":'Permalink to "AI Digest · Sun 08 Nov 2026 <Badge type="tip" text="8" />"'},"​",-1))]),e[3]||(e[3]=t("p",{class:"sub"},"AI Engineer + Better Stack daily digest — 8 Nov 2026 · run date Sun 08 Nov 2026 · 8 videos",-1)),e[4]||(e[4]=t("div",{class:"overview"},[t("p",null,[t("strong",null,"AI Engineer:"),a(" 6 new talks in the last 24 hours, all with full transcripts, and four of them are finance-focused. The freshest are Modal's Akshat Bubna on agent infrastructure (8 Nov, 1:30 AM IST) and OpenAI's 1:50 finance workshop on ChatGPT plugins and Codex (12:30 AM IST). The ones worth watching are Fieldguide's four controls for defensible audit agents and Cohere's Nouha Dziri with hard numbers on multi-agent cost. Kepler's talk mostly repeats Vinoo Ganesh's 25 Oct talk, and the Modal, OpenAI and Nori talks are good to skim.")]),t("p",null,[t("strong",null,"Better Stack:"),a(" 2 new videos. The freshest (8 Nov, 4:49 AM IST) reruns the OPAL experiment, where Claude rewrites the optimizer mid-training, and it's worth watching. The other compares OpenAI's Pando with Anthropic's Scion Git replacement and is worth skimming past the worktree basics.")])],-1)),s(u),e[5]||(e[5]=v('<div class="grid cards2"><article class="it full" id="v-_0SQh8a1Osk" data-title="Don&#39;t Vibe Code Your Agent Infrastructure - Akshat Bubna, Modal" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=_0SQh8a1Osk" target="_blank" rel="noopener"><img src="'+n+'" srcset="'+O+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=_0SQh8a1Osk" target="_blank" rel="noopener">Don&#39;t Vibe Code Your Agent Infrastructure - Akshat Bubna, Modal</a></h3><div class="meta">AI Engineer · Akshat Bubna, CTO of Modal · uploaded 8 Nov, 1:30 AM IST · 17:35</div><div class="verdict v-skim"><b>Verdict:</b> skim from 6:21 — the sandbox basics are familiar, but the Ramp resource data and the scale numbers from 12:12 on are new.</div><div class="repeat">🔁 Repeat: &#39;sandboxes for agents&#39; — seen 22 times before, &#39;agent security&#39; 34 times and &#39;secrets management&#39; 14 times. New here: Real Ramp Inspect resource data, Modal&#39;s scale numbers (20M snapshots a week, 10,000 sandboxes a second for one customer) and the push for path-level network rules via proxy sidecars.</div><div class="sh">What an agent per spreadsheet cell needs</div><ul><li><strong>Every cell is an agent:</strong> Heavy AI&#39;s product runs a spreadsheet query where each cell is backed by its own agent, each in a Modal sandbox that can now hold several containers or microVMs, so the harness (the agent loop) is kept apart from where tool calls run, with a sidecar and shared storage per row; thousands must spin up and down per query <a href="https://www.youtube.com/watch?v=_0SQh8a1Osk&amp;t=24s" target="_blank" rel="noopener">0:24</a>–<a href="https://www.youtube.com/watch?v=_0SQh8a1Osk&amp;t=195s" target="_blank" rel="noopener">3:15</a></li><li><strong>A workspace per agent:</strong> Ramp Inspect, Ramp&#39;s internal coding agent that now pushes almost every PR at Ramp, needs repo, dependencies and dev services together; Basis (accounting) needs documents and work papers; a game studio needs the engine and assets <a href="https://www.youtube.com/watch?v=_0SQh8a1Osk&amp;t=243s" target="_blank" rel="noopener">4:03</a>–<a href="https://www.youtube.com/watch?v=_0SQh8a1Osk&amp;t=300s" target="_blank" rel="noopener">5:00</a></li><li><strong>Persist without paying for idle:</strong> A Basis agent may wait days for an accountant&#39;s reply, so state is kept by snapshotting the whole root filesystem, a single directory like `node_modules`, or a shared volume, and compute runs only while the agent works <a href="https://www.youtube.com/watch?v=_0SQh8a1Osk&amp;t=300s" target="_blank" rel="noopener">5:00</a>–<a href="https://www.youtube.com/watch?v=_0SQh8a1Osk&amp;t=381s" target="_blank" rel="noopener">6:21</a></li><li><strong>Elastic resources:</strong> Ramp&#39;s sandboxes vary hugely in CPU and memory, between sandboxes and over time; provisioning for peak would mean about 15 cores and 15 GB of RAM per sandbox, so Modal grants resources on demand and bills only for that window <a href="https://www.youtube.com/watch?v=_0SQh8a1Osk&amp;t=381s" target="_blank" rel="noopener">6:21</a>–<a href="https://www.youtube.com/watch?v=_0SQh8a1Osk&amp;t=461s" target="_blank" rel="noopener">7:41</a></li></ul><div class="sh">GPUs, collaboration and guardrails</div><ul><li><strong>GPUs on demand:</strong> Claude Science ships with a Modal integration to offload CPU preprocessing or GPU science models; agents hill-climbing a training run in GPU sandboxes can swap GPUs and run ablations in parallel <a href="https://www.youtube.com/watch?v=_0SQh8a1Osk&amp;t=461s" target="_blank" rel="noopener">7:41</a>–<a href="https://www.youtube.com/watch?v=_0SQh8a1Osk&amp;t=542s" target="_blank" rel="noopener">9:02</a></li><li><strong>Shared files and &quot;dreaming&quot;:</strong> Sub-agents and humans share filesystems, and background memory updates are just files, so the filesystem needs speed and consistency (repeat) <a href="https://www.youtube.com/watch?v=_0SQh8a1Osk&amp;t=542s" target="_blank" rel="noopener">9:02</a>–<a href="https://www.youtube.com/watch?v=_0SQh8a1Osk&amp;t=597s" target="_blank" rel="noopener">9:57</a></li><li><strong>Network control beyond domains:</strong> Domain allowlists aren&#39;t enough; users want rules on specific paths of services like Datadog or GitHub, credentials injected so the agent never sees them, and their own lightweight proxy sidecar, as Ramp does <a href="https://www.youtube.com/watch?v=_0SQh8a1Osk&amp;t=597s" target="_blank" rel="noopener">9:57</a>–<a href="https://www.youtube.com/watch?v=_0SQh8a1Osk&amp;t=680s" target="_blank" rel="noopener">11:20</a></li><li><strong>Observability the agent can read:</strong> Failed-training logs, GPU utilization and sandbox budget are exposed to the agent so it can debug and retry by itself <a href="https://www.youtube.com/watch?v=_0SQh8a1Osk&amp;t=680s" target="_blank" rel="noopener">11:20</a>–<a href="https://www.youtube.com/watch?v=_0SQh8a1Osk&amp;t=732s" target="_blank" rel="noopener">12:12</a></li></ul><div class="sh">Why not build it yourself</div><ul><li><strong>Reliability, security, scale:</strong> Modal sees about 20 million snapshots a week, roughly 8 PB of snapshot data a day and 2.6 million new volumes a week; one personal-assistant customer needs 10,000 sandboxes a second, close to a million running, each living 2–3 minutes and interactive in under a second; CPUs are scarce too, so capacity is pooled from several hyperscalers and neoclouds <a href="https://www.youtube.com/watch?v=_0SQh8a1Osk&amp;t=732s" target="_blank" rel="noopener">12:12</a>–<a href="https://www.youtube.com/watch?v=_0SQh8a1Osk&amp;t=894s" target="_blank" rel="noopener">14:54</a></li><li><strong>Pets, cattle, microbes:</strong> With the &quot;brain&quot; (harness) separated from the &quot;hands&quot; (sandbox), harnesses will create, snapshot and discard environments on the fly, more like an ocean of self-evolving microbes than identical cattle <a href="https://www.youtube.com/watch?v=_0SQh8a1Osk&amp;t=894s" target="_blank" rel="noopener">14:54</a>–<a href="https://www.youtube.com/watch?v=_0SQh8a1Osk&amp;t=1030s" target="_blank" rel="noopener">17:10</a></li></ul></div></article><article class="it full" id="v-ZJjRgvjhq3M" data-title="Build Your Own Finance Agent Inside ChatGPT - Stefano Fabbri &amp; Oliver Steffmann, OpenAI" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=ZJjRgvjhq3M" target="_blank" rel="noopener"><img src="'+r+'" srcset="'+R+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=ZJjRgvjhq3M" target="_blank" rel="noopener">Build Your Own Finance Agent Inside ChatGPT - Stefano Fabbri &amp; Oliver Steffmann, OpenAI</a></h3><div class="meta">AI Engineer · Stefano Fabbri &amp; Oliver Steffmann, OpenAI applied AI team (workshop) · uploaded 8 Nov, 12:30 AM IST · 1:50:32</div><div class="verdict v-skim"><b>Verdict:</b> skim from 19:02 to about 1:00:00, then the Q&amp;A from 1:13:00 — the first 18 minutes and much of the middle are workshop setup.</div><div class="repeat">🔁 Repeat: &#39;AI for finance&#39; — seen 31 times before, &#39;MCP servers&#39; 39 times and &#39;agent skills&#39; 19 times. New here: ChatGPT for Financial Services itself was covered in Joseph Kim&#39;s 23 Oct talk; new here are how plugins, plugin extensions and Codex enterprise policies fit together, plus practical cost and eval tips. Long stretches are hands-on setup with little content.</div><div class="sh">ChatGPT for Financial Services (repeat)</div><ul><li><strong>Three surfaces:</strong> ChatGPT, ChatGPT Work (for knowledge workers, runs agents and plugins) and Codex (for engineering work) <a href="https://www.youtube.com/watch?v=ZJjRgvjhq3M&amp;t=297s" target="_blank" rel="noopener">4:57</a>–<a href="https://www.youtube.com/watch?v=ZJjRgvjhq3M&amp;t=340s" target="_blank" rel="noopener">5:40</a></li><li><strong>Built-in data:</strong> Same model, but the product bundles data from Daloopa, LSEG, PitchBook, Crunchbase and others (SEC filings, about 15-minute delayed market data, news, private company profiles, earnings transcripts), each pre-processed into an LLM-friendly format with custom tool calls rather than custom embeddings; enterprise-only and web-only, not reachable from the CLI (repeat) <a href="https://www.youtube.com/watch?v=ZJjRgvjhq3M&amp;t=340s" target="_blank" rel="noopener">5:40</a>–<a href="https://www.youtube.com/watch?v=ZJjRgvjhq3M&amp;t=606s" target="_blank" rel="noopener">10:06</a>, <a href="https://www.youtube.com/watch?v=ZJjRgvjhq3M&amp;t=1860s" target="_blank" rel="noopener">31:00</a>–<a href="https://www.youtube.com/watch?v=ZJjRgvjhq3M&amp;t=2160s" target="_blank" rel="noopener">36:00</a></li><li><strong>Finance plugins:</strong> A plugin is skills plus MCP connections, built with top banks and asset managers; the idea is that the plugin covers about 80% and you customize the last 20% (pitchbook prep, earnings analysis, valuation, LBO modeling) <a href="https://www.youtube.com/watch?v=ZJjRgvjhq3M&amp;t=606s" target="_blank" rel="noopener">10:06</a>–<a href="https://www.youtube.com/watch?v=ZJjRgvjhq3M&amp;t=780s" target="_blank" rel="noopener">13:00</a></li></ul><div class="sh">Building on it with Codex</div><ul><li><strong>Skill, plugin, extension:</strong> A skill is reusable markdown; a plugin zips skills, MCP servers, tool config, auth and UI components; plugin extensions, announced at Dev Day, add your own icons, settings, navigation and context-triggered UI inside the Codex desktop app, with web support still to come <a href="https://www.youtube.com/watch?v=ZJjRgvjhq3M&amp;t=1142s" target="_blank" rel="noopener">19:02</a>–<a href="https://www.youtube.com/watch?v=ZJjRgvjhq3M&amp;t=1680s" target="_blank" rel="noopener">28:00</a>, <a href="https://www.youtube.com/watch?v=ZJjRgvjhq3M&amp;t=3300s" target="_blank" rel="noopener">55:00</a>–<a href="https://www.youtube.com/watch?v=ZJjRgvjhq3M&amp;t=3540s" target="_blank" rel="noopener">59:00</a></li><li><strong>Ship inside an approved surface:</strong> Rather than building a separate app with its own login and access control, deploy a plugin through ChatGPT Work&#39;s plugin creator or the enterprise Codex rollout, connected to internal data through your own MCP server <a href="https://www.youtube.com/watch?v=ZJjRgvjhq3M&amp;t=2900s" target="_blank" rel="noopener">48:20</a>–<a href="https://www.youtube.com/watch?v=ZJjRgvjhq3M&amp;t=3180s" target="_blank" rel="noopener">53:00</a></li><li><strong>Cost tip:</strong> Token efficiency has been clients&#39; top priority for three months; use Astra for new research or codebases, but with good skills the cheaper Luna or 6.1 Sol handle repeatable tasks, and a smart orchestrator with Terra or Luna sub-agents gets about 95% of the result <a href="https://www.youtube.com/watch?v=ZJjRgvjhq3M&amp;t=2520s" target="_blank" rel="noopener">42:00</a>–<a href="https://www.youtube.com/watch?v=ZJjRgvjhq3M&amp;t=2700s" target="_blank" rel="noopener">45:00</a></li><li><strong>Too many skills:</strong> Oliver told one customer they had too many skills; standardize a few core capabilities, and expect skills to survive incremental model updates <a href="https://www.youtube.com/watch?v=ZJjRgvjhq3M&amp;t=3840s" target="_blank" rel="noopener">1:04:00</a>–<a href="https://www.youtube.com/watch?v=ZJjRgvjhq3M&amp;t=4140s" target="_blank" rel="noopener">1:09:00</a></li></ul><div class="sh">Q&amp;A highlights</div><ul><li><strong>Deep research as a plugin:</strong> A planner, sub-agent and critic financial-research app first built on the API was rebuilt as a Codex plugin; the Codex harness (app runner) is open source and OpenAI&#39;s models are post-trained on it; compaction let 5.5 replicate a quant paper on Brownian-motion option pricing over about two hours <a href="https://www.youtube.com/watch?v=ZJjRgvjhq3M&amp;t=4140s" target="_blank" rel="noopener">1:09:00</a>–<a href="https://www.youtube.com/watch?v=ZJjRgvjhq3M&amp;t=4860s" target="_blank" rel="noopener">1:21:00</a></li><li><strong>Sandboxing:</strong> Admins push a managed `config.toml` that limits which URLs, folders and plugins Codex can reach, plus a &quot;guardian&quot; that auto-approves non-critical actions <a href="https://www.youtube.com/watch?v=ZJjRgvjhq3M&amp;t=5280s" target="_blank" rel="noopener">1:28:00</a>–<a href="https://www.youtube.com/watch?v=ZJjRgvjhq3M&amp;t=5520s" target="_blank" rel="noopener">1:32:00</a></li><li><strong>Evals and goal mode:</strong> The hard part of evals is subject-matter knowledge, so start simple before adding an LLM judge, ask the judge yes or no rather than 1–5, and try the new Luna-based Decision API that returns yes/no with a confidence; Codex goal mode hill-climbs a numeric target for autoresearch <a href="https://www.youtube.com/watch?v=ZJjRgvjhq3M&amp;t=5880s" target="_blank" rel="noopener">1:38:00</a>–<a href="https://www.youtube.com/watch?v=ZJjRgvjhq3M&amp;t=6300s" target="_blank" rel="noopener">1:45:00</a></li><li><strong>Writing back:</strong> A proxy-voting plugin writes reports and sources back to an app server through an extension, keeping auditable logs of every decision <a href="https://www.youtube.com/watch?v=ZJjRgvjhq3M&amp;t=6420s" target="_blank" rel="noopener">1:47:00</a>–<a href="https://www.youtube.com/watch?v=ZJjRgvjhq3M&amp;t=6600s" target="_blank" rel="noopener">1:50:00</a></li></ul></div></article><article class="it full" id="v-gdzsJZJ6DDs" data-title="Your Financial Agent Needs to Show Its Work - Anirudh Veeraragavan, Fieldguide" data-channel="AI Engineer" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=gdzsJZJ6DDs" target="_blank" rel="noopener"><img src="'+i+'" srcset="'+M+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=gdzsJZJ6DDs" target="_blank" rel="noopener">Your Financial Agent Needs to Show Its Work - Anirudh Veeraragavan, Fieldguide</a></h3><div class="meta">AI Engineer · Anirudh Veeraragavan, Fieldguide · uploaded 7 Nov, 11:30 PM IST · 13:28</div><div class="verdict v-worth"><b>Verdict:</b> worth watching — short, concrete and reusable for any regulated agent.</div><div class="repeat">🔁 Repeat: &#39;AI for finance&#39; — seen 31 times before, &#39;human-in-the-loop review&#39; 35 times and &#39;evals for agents&#39; 62 times. New here: A tight four-control framework (state-aware authorization, replayable step records, versioned and hashed citations, auditing the eval set itself) worked through one bank reconciliation.</div><div class="sh">Why &quot;the model said so&quot; fails</div><ul><li><strong>The opinion is the product:</strong> In audit what matters is the reasoning behind a decision; when an inspector asks why a test was sufficient, your evals and metrics don&#39;t answer it <a href="https://www.youtube.com/watch?v=gdzsJZJ6DDs&amp;t=0s" target="_blank" rel="noopener">0:00</a>–<a href="https://www.youtube.com/watch?v=gdzsJZJ6DDs&amp;t=138s" target="_blank" rel="noopener">2:18</a></li><li><strong>Stakes:</strong> Peregrine Financial Group claimed over $200 million in its accounts for 20 years while the bank held only $5 million <a href="https://www.youtube.com/watch?v=gdzsJZJ6DDs&amp;t=138s" target="_blank" rel="noopener">2:18</a>–<a href="https://www.youtube.com/watch?v=gdzsJZJ6DDs&amp;t=185s" target="_blank" rel="noopener">3:05</a></li><li><strong>The bar:</strong> An experienced auditor new to the work must be able to follow the agent; the example is a fictional freight-lines client with $2.9M at the bank, $2.7M on the books and 41 reconciling items <a href="https://www.youtube.com/watch?v=gdzsJZJ6DDs&amp;t=185s" target="_blank" rel="noopener">3:05</a>–<a href="https://www.youtube.com/watch?v=gdzsJZJ6DDs&amp;t=267s" target="_blank" rel="noopener">4:27</a></li></ul><div class="sh">Four controls</div><ul><li><strong>Authorization:</strong> The agent correctly flipped a human-flagged check to &quot;no exception&quot; after new evidence, but it shouldn&#39;t have, because the reviewer&#39;s sign-off no longer matched what they saw; permission depends on the object, its state and the time, so agents draft only unreviewed rows <a href="https://www.youtube.com/watch?v=gdzsJZJ6DDs&amp;t=267s" target="_blank" rel="noopener">4:27</a>–<a href="https://www.youtube.com/watch?v=gdzsJZJ6DDs&amp;t=337s" target="_blank" rel="noopener">5:37</a></li><li><strong>Execution records:</strong> Logs can&#39;t explain why a 2028 rerun disagrees with the 2027 run; a chain of steps with IDs, inputs and outputs, marked deterministic or LLM, lets you rerun one step and find exactly where the runs diverge <a href="https://www.youtube.com/watch?v=gdzsJZJ6DDs&amp;t=337s" target="_blank" rel="noopener">5:37</a>–<a href="https://www.youtube.com/watch?v=gdzsJZJ6DDs&amp;t=453s" target="_blank" rel="noopener">7:33</a></li><li><strong>Evidence provenance:</strong> A citation like &quot;January bank statement, page 2&quot; is useless; a citation is an identity with a document ID, version and content hash, which lets you enforce rules like bank-sourced evidence only <a href="https://www.youtube.com/watch?v=gdzsJZJ6DDs&amp;t=453s" target="_blank" rel="noopener">7:33</a>–<a href="https://www.youtube.com/watch?v=gdzsJZJ6DDs&amp;t=524s" target="_blank" rel="noopener">8:44</a></li><li><strong>Eval integrity:</strong> Gold data from past reviewed audits can be wrong; of 9 misses behind a 97% score, 4 were eval errors, while 12 &quot;correct&quot; cases were actually wrong after methodology changes <a href="https://www.youtube.com/watch?v=gdzsJZJ6DDs&amp;t=524s" target="_blank" rel="noopener">8:44</a>–<a href="https://www.youtube.com/watch?v=gdzsJZJ6DDs&amp;t=609s" target="_blank" rel="noopener">10:09</a></li></ul><div class="sh">When to hand off</div><ul><li><strong>Stop and ask:</strong> Escalate when the agent would overwrite reviewed work, runs disagree, or evidence breaks the rules; make escalations easy to verify but not easy to approve, because of automation bias, and aim for the agent handling about 80% <a href="https://www.youtube.com/watch?v=gdzsJZJ6DDs&amp;t=609s" target="_blank" rel="noopener">10:09</a>–<a href="https://www.youtube.com/watch?v=gdzsJZJ6DDs&amp;t=736s" target="_blank" rel="noopener">12:16</a></li><li><strong>Beyond audit:</strong> The same four questions apply to approving or declining credit and to closing or escalating anti-money-laundering alerts <a href="https://www.youtube.com/watch?v=gdzsJZJ6DDs&amp;t=736s" target="_blank" rel="noopener">12:16</a>–<a href="https://www.youtube.com/watch?v=gdzsJZJ6DDs&amp;t=790s" target="_blank" rel="noopener">13:10</a></li></ul></div></article><article class="it full" id="v-maitMe9HCvw" data-title="How to Get Frontier Coding Results at 70% Lower Cost - Nouha Dziri, Cohere" data-channel="AI Engineer" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=maitMe9HCvw" target="_blank" rel="noopener"><img src="'+l+'" srcset="'+x+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=maitMe9HCvw" target="_blank" rel="noopener">How to Get Frontier Coding Results at 70% Lower Cost - Nouha Dziri, Cohere</a></h3><div class="meta">AI Engineer · Nouha Dziri, Cohere · uploaded 7 Nov, 1:30 PM IST · 31:22</div><div class="verdict v-worth"><b>Verdict:</b> worth watching — rare controlled numbers on multi-agent cost versus reward.</div><div class="repeat">🔁 Repeat: &#39;multi-agent / A2A&#39; — seen 20 times before, &#39;token costs / AI spend&#39; 21 times and &#39;coding agents in production&#39; 70 times. New here: Actual experimental numbers on where extra agents pay off (planning on ProgramBench, implementation on Commit0), lead-versus-worker model mixing and how little agents talk to each other.</div><div class="sh">Setting up the experiment</div><ul><li><strong>Teams as a new axis:</strong> Besides thinking longer or sampling more, a lead can split work among workers with fresh contexts that report back compact results; left alone, frontier agents mostly built their own versions and stepped on each other <a href="https://www.youtube.com/watch?v=maitMe9HCvw&amp;t=0s" target="_blank" rel="noopener">0:00</a>–<a href="https://www.youtube.com/watch?v=maitMe9HCvw&amp;t=240s" target="_blank" rel="noopener">4:00</a></li><li><strong>Minimal harness:</strong> A hierarchical lead with a `delegate_agent` tool and a shared bash workspace, tested with a blocking lead (waits for workers) or an async lead, on ProgramBench, where agents must reimplement a program they can run but not read; on FFmpeg the best model passes only 10% of tests <a href="https://www.youtube.com/watch?v=maitMe9HCvw&amp;t=300s" target="_blank" rel="noopener">5:00</a>–<a href="https://www.youtube.com/watch?v=maitMe9HCvw&amp;t=460s" target="_blank" rel="noopener">7:40</a></li><li><strong>Teams win, at a price:</strong> A team beats a solo agent by almost 10 points but costs 4–7 times as much; the async lead builds on guesses and sometimes submits while workers are still running <a href="https://www.youtube.com/watch?v=maitMe9HCvw&amp;t=460s" target="_blank" rel="noopener">7:40</a>–<a href="https://www.youtube.com/watch?v=maitMe9HCvw&amp;t=540s" target="_blank" rel="noopener">9:00</a></li><li><strong>Heavy prompting helps:</strong> A detailed plan-implement-verify prompt lifts even the solo agent by about 6 points and lets the async lead catch up, but costs stay 6–7 times higher <a href="https://www.youtube.com/watch?v=maitMe9HCvw&amp;t=540s" target="_blank" rel="noopener">9:00</a>–<a href="https://www.youtube.com/watch?v=maitMe9HCvw&amp;t=660s" target="_blank" rel="noopener">11:00</a></li></ul><div class="sh">Where the next dollar goes</div><ul><li><strong>Put workers at the bottleneck:</strong> Planning-only workers on ProgramBench match the heavy-prompt team at half the cost, with each planning dollar buying about 1.6 times more reward; implementation or verification workers add cost only, and the heavy-prompt lead made 830 more delegation calls (around $500) for nothing; on Commit0 the bottleneck is implementation instead <a href="https://www.youtube.com/watch?v=maitMe9HCvw&amp;t=660s" target="_blank" rel="noopener">11:00</a>–<a href="https://www.youtube.com/watch?v=maitMe9HCvw&amp;t=1200s" target="_blank" rel="noopener">20:00</a></li><li><strong>Strong lead, cheap workers:</strong> With GPT-5.6 Luna, Terra and Sol, a Sol lead with Luna workers nearly matches all-Sol at 60% lower cost, but cheap workers can&#39;t rescue a weak lead: Terra with Luna workers scored 51% against Sol alone at 57% (&quot;the lead sets the ceiling, the workers set the price&quot;) <a href="https://www.youtube.com/watch?v=maitMe9HCvw&amp;t=1200s" target="_blank" rel="noopener">20:00</a>–<a href="https://www.youtube.com/watch?v=maitMe9HCvw&amp;t=1320s" target="_blank" rel="noopener">22:00</a></li><li><strong>Scale planners:</strong> Going from 2 to 16 Luna planners, the 16-planner team is 38% cheaper than an all-Sol planning team and 70% cheaper than workers at every stage <a href="https://www.youtube.com/watch?v=maitMe9HCvw&amp;t=1320s" target="_blank" rel="noopener">22:00</a>–<a href="https://www.youtube.com/watch?v=maitMe9HCvw&amp;t=1440s" target="_blank" rel="noopener">24:00</a></li></ul><div class="sh">How agents actually talk</div><ul><li><strong>Hierarchy by default:</strong> 84% of messages go worker to lead, with less than one worker-to-worker message per task; about half of Luna&#39;s messages were malformed, and messaging added nothing for Sol and Terra while costing Luna teams 4–7 points <a href="https://www.youtube.com/watch?v=maitMe9HCvw&amp;t=1440s" target="_blank" rel="noopener">24:00</a>–<a href="https://www.youtube.com/watch?v=maitMe9HCvw&amp;t=1620s" target="_blank" rel="noopener">27:00</a></li><li><strong>Not every model leads:</strong> GPT-5.6 delegates often and gains up to 7 points and Claude gains about 6, while Opus 4.7 rarely delegates and Gemini delegates a lot but gains nothing <a href="https://www.youtube.com/watch?v=maitMe9HCvw&amp;t=1620s" target="_blank" rel="noopener">27:00</a>–<a href="https://www.youtube.com/watch?v=maitMe9HCvw&amp;t=1680s" target="_blank" rel="noopener">28:00</a></li><li><strong>Open questions:</strong> Organizing thousands of agents, letting agents design their own team, and multi-agent safety for swarms running 24/7 <a href="https://www.youtube.com/watch?v=maitMe9HCvw&amp;t=1680s" target="_blank" rel="noopener">28:00</a>–<a href="https://www.youtube.com/watch?v=maitMe9HCvw&amp;t=1882s" target="_blank" rel="noopener">31:22</a></li></ul></div></article><article class="it full" id="v-RdQCY_-SXbA" data-title="AI Can&#39;t Make Up a Number It Can&#39;t Look Up - Vinoo Ganesh, Kepler" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=RdQCY_-SXbA" target="_blank" rel="noopener"><img src="'+h+'" srcset="'+D+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=RdQCY_-SXbA" target="_blank" rel="noopener">AI Can&#39;t Make Up a Number It Can&#39;t Look Up - Vinoo Ganesh, Kepler</a></h3><div class="meta">AI Engineer · Vinoo Ganesh, Kepler (ex-Citadel) · uploaded 7 Nov, 1:30 PM IST · 18:28</div><div class="verdict v-skim"><b>Verdict:</b> skim from 4:17 — if you saw his 25 Oct talk, only the retrieval funnel and tenant-security list (9:07–12:25) are new.</div><div class="repeat">🔁 Repeat: &#39;AI for finance&#39; — seen 31 times before. New here: Same speaker and core architecture as his 25 Oct talk &quot;Do Not Let Models Invent Numbers&quot;; the new parts are the three-way breakdown of wrong numbers, the retrieval funnel numbers and five tenant-security failure modes.</div><div class="sh">Why Wall Street still doesn&#39;t trust AI</div><ul><li><strong>Verification gold rush:</strong> About $270 million of VC money went into verification layers in three months, and a VC handed Kepler&#39;s deck to a competitor, which copied the verification step but not the structure behind it <a href="https://www.youtube.com/watch?v=RdQCY_-SXbA&amp;t=0s" target="_blank" rel="noopener">0:00</a>–<a href="https://www.youtube.com/watch?v=RdQCY_-SXbA&amp;t=120s" target="_blank" rel="noopener">2:00</a></li><li><strong>Hallucination is alpha:</strong> Firms make money on creativity, so the fix is structural, not waiting for models to stop making things up; trust means someone to blame, and while 80% of finance execs trust their numbers, 31% find errors <a href="https://www.youtube.com/watch?v=RdQCY_-SXbA&amp;t=120s" target="_blank" rel="noopener">2:00</a>–<a href="https://www.youtube.com/watch?v=RdQCY_-SXbA&amp;t=257s" target="_blank" rel="noopener">4:17</a></li><li><strong>Three sources of wrong numbers:</strong> The wrong document, the wrong number from the right document (Palantir&#39;s 2023 revenue read off its 2025 10-K) and models doing math by predicting tokens <a href="https://www.youtube.com/watch?v=RdQCY_-SXbA&amp;t=257s" target="_blank" rel="noopener">4:17</a>–<a href="https://www.youtube.com/watch?v=RdQCY_-SXbA&amp;t=350s" target="_blank" rel="noopener">5:50</a></li></ul><div class="sh">How Kepler is built (repeat)</div><ul><li><strong>Code writes every number:</strong> Pre-processing turns every fact into an ID; the model plans and points to IDs, and if it can&#39;t dereference a pointer it can&#39;t print the number (repeat) <a href="https://www.youtube.com/watch?v=RdQCY_-SXbA&amp;t=350s" target="_blank" rel="noopener">5:50</a>–<a href="https://www.youtube.com/watch?v=RdQCY_-SXbA&amp;t=547s" target="_blank" rel="noopener">9:07</a></li><li><strong>Search wide, then narrow:</strong> ANN plus BM25 pulls up to 200 documents, reciprocal rank fusion cuts to about 60, then cross-encoders rerank; LLMs tend to search depth-first because going wide is expensive <a href="https://www.youtube.com/watch?v=RdQCY_-SXbA&amp;t=547s" target="_blank" rel="noopener">9:07</a>–<a href="https://www.youtube.com/watch?v=RdQCY_-SXbA&amp;t=646s" target="_blank" rel="noopener">10:46</a></li><li><strong>Tenant security:</strong> Five ways it goes wrong: forgetting the tenant filter (Citadel seeing Millennium&#39;s documents), a caller impersonating another firm, stale results, direct reads skipping search rules and hitting an unpopulated index; the fix is scoping every search with security built in <a href="https://www.youtube.com/watch?v=RdQCY_-SXbA&amp;t=646s" target="_blank" rel="noopener">10:46</a>–<a href="https://www.youtube.com/watch?v=RdQCY_-SXbA&amp;t=745s" target="_blank" rel="noopener">12:25</a></li><li><strong>Verified, corrected or refused:</strong> Refusals dropped sharply in production but not to zero, so a post-processing check stays; today most finance AI tools mostly format PowerPoint decks <a href="https://www.youtube.com/watch?v=RdQCY_-SXbA&amp;t=840s" target="_blank" rel="noopener">14:00</a>–<a href="https://www.youtube.com/watch?v=RdQCY_-SXbA&amp;t=991s" target="_blank" rel="noopener">16:31</a></li><li><strong>Ask your vendor:</strong> Does the model write pointers, is every citation and every arithmetic step source-checked, and what happens to a number that came from nowhere <a href="https://www.youtube.com/watch?v=RdQCY_-SXbA&amp;t=991s" target="_blank" rel="noopener">16:31</a>–<a href="https://www.youtube.com/watch?v=RdQCY_-SXbA&amp;t=1108s" target="_blank" rel="noopener">18:28</a></li></ul></div></article><article class="it full" id="v-kIlVNGZZr8o" data-title="How Agents Cut Hour-Long Data Checks to 5 Minutes - Amol Kapoor &amp; Clifford Ressel, Nori Agentic" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=kIlVNGZZr8o" target="_blank" rel="noopener"><img src="'+c+'" srcset="'+N+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=kIlVNGZZr8o" target="_blank" rel="noopener">How Agents Cut Hour-Long Data Checks to 5 Minutes - Amol Kapoor &amp; Clifford Ressel, Nori Agentic</a></h3><div class="meta">AI Engineer · Amol Kapoor &amp; Clifford Ressel, Nori Agentic · uploaded 7 Nov, 12:30 PM IST · 19:34</div><div class="verdict v-skim"><b>Verdict:</b> skim from 10:50 — the first ten minutes are a finance primer, and the agent pattern itself is familiar.</div><div class="repeat">🔁 Repeat: &#39;AI for finance&#39; — seen 31 times before and &#39;human-in-the-loop review&#39; 35 times. New here: The security-master problem (how asset managers map instruments) and a concrete before/after at a Fortune 200 asset manager.</div><div class="sh">Why private assets break the data</div><ul><li><strong>Finance got weird:</strong> Secondaries volume hit $240 billion in 2025, up 50%, with forecasts of $32 trillion in alternative assets by 2030; private-asset terms live in PDFs, Box folders, Outlook and Zoom transcripts <a href="https://www.youtube.com/watch?v=kIlVNGZZr8o&amp;t=21s" target="_blank" rel="noopener">0:21</a>–<a href="https://www.youtube.com/watch?v=kIlVNGZZr8o&amp;t=204s" target="_blank" rel="noopener">3:24</a></li><li><strong>What a security master is:</strong> The firm&#39;s master database of every instrument it holds, feeding risk, P&amp;L and compliance, joined across vendors through identifiers like Bloomberg FIGIs, LSEG RICs, ISINs and CUSIPs <a href="https://www.youtube.com/watch?v=kIlVNGZZr8o&amp;t=259s" target="_blank" rel="noopener">4:19</a>–<a href="https://www.youtube.com/watch?v=kIlVNGZZr8o&amp;t=423s" target="_blank" rel="noopener">7:03</a></li><li><strong>Even Google is messy:</strong> GOOG versus GOOGL share classes, entity-level data that won&#39;t join on ISIN and the same share on several exchanges; private deals have no shared identifiers at all, so data grows one-to-one with assets <a href="https://www.youtube.com/watch?v=kIlVNGZZr8o&amp;t=423s" target="_blank" rel="noopener">7:03</a>–<a href="https://www.youtube.com/watch?v=kIlVNGZZr8o&amp;t=650s" target="_blank" rel="noopener">10:50</a></li></ul><div class="sh">The agent in production</div><ul><li><strong>Before:</strong> A Fortune 200 asset manager diffs about 50,000 assets by about 200 columns every day, and each changed cell took about an hour of manual checking <a href="https://www.youtube.com/watch?v=kIlVNGZZr8o&amp;t=650s" target="_blank" rel="noopener">10:50</a>–<a href="https://www.youtube.com/watch?v=kIlVNGZZr8o&amp;t=754s" target="_blank" rel="noopener">12:34</a></li><li><strong>After:</strong> For each change a cloud agent spins up, running a locally deployed open-source model so data stays on-prem, checks Box PDFs, Bloomberg and a slice of email, writes an explanation with citations, recommends keep or discard and pings the cell&#39;s owner in Slack; the human part drops to about 5 minutes <a href="https://www.youtube.com/watch?v=kIlVNGZZr8o&amp;t=754s" target="_blank" rel="noopener">12:34</a>–<a href="https://www.youtube.com/watch?v=kIlVNGZZr8o&amp;t=877s" target="_blank" rel="noopener">14:37</a></li><li><strong>Expertise in plain English:</strong> A generic agent (Claude Code, OpenCode, Pi) customized with skills and agent markdown files rather than custom infrastructure (repeat) <a href="https://www.youtube.com/watch?v=kIlVNGZZr8o&amp;t=877s" target="_blank" rel="noopener">14:37</a>–<a href="https://www.youtube.com/watch?v=kIlVNGZZr8o&amp;t=935s" target="_blank" rel="noopener">15:35</a></li><li><strong>Agents come to you:</strong> The same cloud-agent infrastructure should run SecMaster, audit and code-review agents, with only instructions, tools and triggers differing <a href="https://www.youtube.com/watch?v=kIlVNGZZr8o&amp;t=935s" target="_blank" rel="noopener">15:35</a>–<a href="https://www.youtube.com/watch?v=kIlVNGZZr8o&amp;t=1039s" target="_blank" rel="noopener">17:19</a></li></ul><div class="sh">Lessons</div><ul><li><strong>Three takeaways:</strong> Adoption is a collaboration problem between domain experts and engineers; aim for 95% automation and keep a human in the loop; and agents make &quot;accidental complexity&quot; (Fred Brooks&#39;s term) cheap to handle <a href="https://www.youtube.com/watch?v=kIlVNGZZr8o&amp;t=1039s" target="_blank" rel="noopener">17:19</a>–<a href="https://www.youtube.com/watch?v=kIlVNGZZr8o&amp;t=1140s" target="_blank" rel="noopener">19:00</a></li></ul></div></article><article class="it full" id="v-0acRokoODvo" data-title="Did Claude Just Fix AI Overfitting? (OPAL)" data-channel="Better Stack" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=0acRokoODvo" target="_blank" rel="noopener"><img src="'+p+'" srcset="'+J+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">Better Stack</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=0acRokoODvo" target="_blank" rel="noopener">Did Claude Just Fix AI Overfitting? (OPAL)</a></h3><div class="meta">Better Stack · Andress (Better Stack) · uploaded 8 Nov, 4:49 AM IST · 8:48</div><div class="verdict v-worth"><b>Verdict:</b> worth watching — a clear, honest replication of an agent-in-the-training-loop idea.</div><div class="sh">The experiment</div><ul><li><strong>Sabotaged data:</strong> Two copies of a ResNet-18 trained on CIFAR-10 at the same time, with 4,500 of 45,000 training labels deliberately wrong; the agent sees scores on 5,000 clean images, and 10,000 test images are held back; run on one rented H100 on RunPod with Claude Opus 5.5 as the agent <a href="https://www.youtube.com/watch?v=0acRokoODvo&amp;t=0s" target="_blank" rel="noopener">0:00</a>–<a href="https://www.youtube.com/watch?v=0acRokoODvo&amp;t=224s" target="_blank" rel="noopener">3:44</a></li><li><strong>What OPAL is:</strong> A PyTorch library from the &quot;Reactive Optimizers&quot; paper that wraps your optimizer, pauses training now and then, hands an agent a report and lets it rewrite the optimizer&#39;s code but not the model, data or eval; the paper improved an image model&#39;s FID from about 36 to 24, with small gains on already-tuned recipes <a href="https://www.youtube.com/watch?v=0acRokoODvo&amp;t=56s" target="_blank" rel="noopener">0:56</a>–<a href="https://www.youtube.com/watch?v=0acRokoODvo&amp;t=162s" target="_blank" rel="noopener">2:42</a></li></ul><div class="sh">What Claude did</div><ul><li><strong>Early tries:</strong> It replaced the optimizer with its own update rule at once, spotted overfitting around epoch 24, then failed with flooding, weight noise and last-layer flooding (accuracy fell to about 52%), noting &quot;Never use flooding again&quot; <a href="https://www.youtube.com/watch?v=0acRokoODvo&amp;t=224s" target="_blank" rel="noopener">3:44</a>–<a href="https://www.youtube.com/watch?v=0acRokoODvo&amp;t=300s" target="_blank" rel="noopener">5:00</a></li><li><strong>The pivot:</strong> It let the model take big noisy steps while keeping a running weight average, which lifted clean accuracy to 78%; when it found the model still about 89% memorized it wrote &quot;my mechanism was wrong&quot;, and bigger steps then cut memorization from about 87% to 4% <a href="https://www.youtube.com/watch?v=0acRokoODvo&amp;t=300s" target="_blank" rel="noopener">5:00</a>–<a href="https://www.youtube.com/watch?v=0acRokoODvo&amp;t=353s" target="_blank" rel="noopener">5:53</a></li><li><strong>Results:</strong> 79.1% versus 74.4% test accuracy, loss 0.70 versus 2.39, and only 250 of the 4,500 wrong labels memorized versus all of them for the fixed recipe; the paper&#39;s released run got 80% <a href="https://www.youtube.com/watch?v=0acRokoODvo&amp;t=353s" target="_blank" rel="noopener">5:53</a>–<a href="https://www.youtube.com/watch?v=0acRokoODvo&amp;t=422s" target="_blank" rel="noopener">7:02</a></li></ul><div class="sh">Caveats</div><ul><li><strong>Not new math:</strong> What Claude landed on is close to stochastic weight averaging from 2018, and plain fixed averaging alone got about 77.5%; it was one small run, the agent run took over three times longer waiting on Claude, and the captions put its token cost at about $760 <a href="https://www.youtube.com/watch?v=0acRokoODvo&amp;t=422s" target="_blank" rel="noopener">7:02</a>–<a href="https://www.youtube.com/watch?v=0acRokoODvo&amp;t=528s" target="_blank" rel="noopener">8:48</a></li></ul></div></article><article class="it full" id="v-ZtOA71C_Nco" data-title="Anthropic Replaced Git. OpenAI Did the Opposite." data-channel="Better Stack" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=ZtOA71C_Nco" target="_blank" rel="noopener"><img src="'+w+'" srcset="'+j+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">Better Stack</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=ZtOA71C_Nco" target="_blank" rel="noopener">Anthropic Replaced Git. OpenAI Did the Opposite.</a></h3><div class="meta">Better Stack · Josh (Better Stack) · uploaded 7 Nov, 5:45 PM IST · 9:18</div><div class="verdict v-skim"><b>Verdict:</b> skim from 2:46 — skip the worktree basics; the Pando and Scion comparison is the new part.</div><div class="repeat">🔁 Repeat: &#39;coding agents in production&#39; — seen 70 times before and &#39;merge queues / CI&#39; 6 times. New here: OpenAI&#39;s Pando and Anthropic&#39;s Scion source-control numbers; the Git worktree demo repeats Better Stack&#39;s 31 Oct Worktrunk video.</div><div class="sh">The problem</div><ul><li><strong>Agents overload Git:</strong> Anthropic went from about 2,500 to over 30,000 merged code changes a day in 4 months, and OpenAI&#39;s monorepo reliability sometimes fell below 90% <a href="https://www.youtube.com/watch?v=ZtOA71C_Nco&amp;t=0s" target="_blank" rel="noopener">0:00</a>–<a href="https://www.youtube.com/watch?v=ZtOA71C_Nco&amp;t=46s" target="_blank" rel="noopener">0:46</a></li><li><strong>Worktrees for now:</strong> Two commands give each agent its own folder and branch so they stop editing the same files; it doesn&#39;t remove later merge conflicts (repeat) <a href="https://www.youtube.com/watch?v=ZtOA71C_Nco&amp;t=46s" target="_blank" rel="noopener">0:46</a>–<a href="https://www.youtube.com/watch?v=ZtOA71C_Nco&amp;t=166s" target="_blank" rel="noopener">2:46</a></li></ul><div class="sh">Two fixes</div><ul><li><strong>OpenAI Pando:</strong> A new Git backend that handles updates to different branches immediately and caches pack files for CI, at the cost of cross-branch reads not being perfectly in sync; median push latency fell by nearly 80%, it serves most of a petabyte a day, and one engineer designed the core, mostly implemented by Codex, in about 10 weeks <a href="https://www.youtube.com/watch?v=ZtOA71C_Nco&amp;t=166s" target="_blank" rel="noopener">2:46</a>–<a href="https://www.youtube.com/watch?v=ZtOA71C_Nco&amp;t=235s" target="_blank" rel="noopener">3:55</a></li><li><strong>Anthropic Scion:</strong> A full Git replacement for a main branch history near 100 GB and about 25 million CI checkouts a day, mostly agents; clients fetch only the files they need and commits, merges and history run on the server; about 200 times less CPU and memory than the old Git mirroring, checkouts from minutes to seconds and about 25% of CI CPU recovered, but code review, search and CI had to be rebuilt <a href="https://www.youtube.com/watch?v=ZtOA71C_Nco&amp;t=235s" target="_blank" rel="noopener">3:55</a>–<a href="https://www.youtube.com/watch?v=ZtOA71C_Nco&amp;t=300s" target="_blank" rel="noopener">5:00</a></li></ul><div class="sh">What to do yourself</div><ul><li><strong>Caveats:</strong> Neither is usable today, and the numbers are self-reported on workloads most teams never see; OpenAI is upstreaming some Git client improvements <a href="https://www.youtube.com/watch?v=ZtOA71C_Nco&amp;t=300s" target="_blank" rel="noopener">5:00</a>–<a href="https://www.youtube.com/watch?v=ZtOA71C_Nco&amp;t=398s" target="_blank" rel="noopener">6:38</a></li><li><strong>Four practical steps:</strong> Use worktrees per agent, sparse checkouts in big repos, and CI caching, duplicate-job removal and running only relevant tests; review and validation become the next bottleneck <a href="https://www.youtube.com/watch?v=ZtOA71C_Nco&amp;t=398s" target="_blank" rel="noopener">6:38</a>–<a href="https://www.youtube.com/watch?v=ZtOA71C_Nco&amp;t=540s" target="_blank" rel="noopener">9:00</a></li></ul></div></article></div>',1))])}const F=m(Z,[["render",P]]);export{H as __pageData,F as default};
